"use client";import{createClient}from"@/lib/supabase/client";import{useRouter}from"next/navigation";export default function VendorClient({vendor,orders}:{vendor:any,orders:any[]}){const s=createClient(),r=useRouter();async function online(){await s.from("vendor_profiles").update({is_available:!vendor.is_available}).eq("user_id",vendor.user_id);r.refresh()}async function respond(id:number,yes:boolean){await s.rpc("vendor_respond_offer",{p_order_id:id,p_accept:yes});if(!yes)await s.rpc("assign_nearest_vendor",{p_order_id:id});r.refresh()}async function status(id:number,x:string){await s.rpc("vendor_set_order_status",{p_order_id:id,p_status:x});r.refresh()}return <><section className="card"><b>{vendor.business_name}</b><p>{vendor.status} · {vendor.is_available?"Online":"Offline"}</p><button className="btn alt" onClick={online}>{vendor.is_available?"Go offline":"Go online"}</button></section>{orders.map(o=><section className="card" key={o.id}><div className="row"><b>{o.order_code}</b><span className="badge">{o.status}</span></div><p>{o.quantity_kg} kg · {o.delivery_address}</p>{o.status==="offered"&&<div className="twocol"><button className="btn" onClick={()=>respond(o.id,true)}>Accept</button><button className="btn danger" onClick={()=>respond(o.id,false)}>Decline</button></div>}{o.status==="accepted"&&<button className="btn" onClick={()=>status(o.id,"preparing")}>Start preparing</button>}{o.status==="preparing"&&<button className="btn" onClick={()=>status(o.id,"out_for_delivery")}>Mark out for delivery</button>}{o.status==="out_for_delivery"&&<button className="btn" onClick={()=>status(o.id,"delivered")}>Confirm delivered</button>}</section>)}</>}